"""Grafana is provisioned as code; dashboards are generated by grafana/build_dashboards.py."""

import importlib.util
import json
import re
from pathlib import Path
from typing import Any

import yaml

ROOT = Path(__file__).resolve().parents[1]
GRAFANA = ROOT / "grafana"

SPEC = importlib.util.spec_from_file_location("build_dashboards", GRAFANA / "build_dashboards.py")
assert SPEC and SPEC.loader
build_dashboards = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(build_dashboards)


def dashboards() -> dict[str, dict[str, Any]]:
    return {
        path.name: json.loads(path.read_text()) for path in (GRAFANA / "dashboards").glob("*.json")
    }


def test_committed_dashboards_match_the_builder() -> None:
    rendered = build_dashboards.render_all()
    committed = {name: (GRAFANA / "dashboards" / name).read_text() for name in rendered}
    assert committed == rendered, "Run `make grafana-dashboards` and commit the JSON."
    assert set(rendered) == set(dashboards())


def test_the_four_operational_dashboards_and_the_public_one_exist() -> None:
    titles = {model["title"] for model in dashboards().values()}
    assert titles == {
        "Live Network Overview",
        "Station Drilldown",
        "Rebalancing Board",
        "Daily Review",
        "Dockline Live (public)",
    }


def test_every_panel_metric_comes_from_cube() -> None:
    for name, model in dashboards().items():
        for panel in model["panels"]:
            for target in panel.get("targets", []):
                assert target["datasource"]["uid"] == "cube", (name, panel["title"])
                assert "MEASURE(" in target["rawSql"] or "GROUP BY" in target["rawSql"], panel[
                    "title"
                ]


def test_live_dashboards_refresh_every_10_seconds() -> None:
    models = dashboards()
    for name in ("live-network-overview.json", "rebalancing-board.json", "public-live.json"):
        assert models[name]["refresh"] == "10s"


def test_public_dashboard_has_no_variables_and_carries_the_disclaimer() -> None:
    model = dashboards()["public-live.json"]
    assert model["templating"]["list"] == []
    texts = [panel["options"]["content"] for panel in model["panels"] if panel["type"] == "text"]
    assert any("Not affiliated with Citi Bike or Lyft" in text for text in texts)


def test_state_colors_match_the_design_system() -> None:
    assert build_dashboards.STATE_COLORS == {
        "starving": "#E0701F",
        "balanced": "#A9B3C1",
        "flooding": "#2357C6",
        "offline": "#7A6F9B",
    }


def test_alert_rules_cover_the_three_required_conditions() -> None:
    rules = yaml.safe_load((GRAFANA / "provisioning" / "alerting" / "rules.yml").read_text())
    by_uid = {rule["uid"]: rule for group in rules["groups"] for rule in group["rules"]}
    assert set(by_uid) == {
        "dockline-feed-stale",
        "dockline-high-traffic-empty",
        "dockline-ingestion-failure",
    }
    stale_sql = by_uid["dockline-feed-stale"]["data"][0]["model"]["rawSql"]
    assert "data_freshness_seconds" in stale_sql
    assert by_uid["dockline-feed-stale"]["noDataState"] == "Alerting"
    thresholds = {
        uid: rule["data"][2]["model"]["conditions"][0]["evaluator"]["params"][0]
        for uid, rule in by_uid.items()
    }
    assert thresholds == {
        "dockline-feed-stale": 300,
        "dockline-high-traffic-empty": 10,
        "dockline-ingestion-failure": 0,
    }


def test_datasource_credentials_come_from_the_environment() -> None:
    text = (GRAFANA / "provisioning" / "datasources" / "datasources.yml").read_text()
    for password in re.findall(r"password:\s*(\S+)", text):
        assert password.startswith("$__env{"), password
